export const savePersistedState = (key, value) => {
  window.localStorage.setItem(key, JSON.stringify(value));
  broadcast(key, value);
};

export default (key, defaultValue) => {
  const defaultRef = useRef(defaultValue);

  const [value, setValue] = useState(() => {
    const stickyValue = window.localStorage.getItem(key);
    return stickyValue ? JSON.parse(stickyValue) : defaultRef.current;
  });

  useEffect(() => {
    if (!listeners.has(key)) {
      listeners.set(key, new Set());
    }
    listeners.get(key).add(setValue);
    return () => listeners.get(key).delete(setValue);
  }, [key]);

  useEffect(() => {
    if (value !== defaultRef.current) {
      window.localStorage.setItem(key, JSON.stringify(value));
    } else {
      window.localStorage.removeItem(key);
    }
    broadcast(key, value);
  }, [key, value]);

  return [value, setValue];
};","lineStart":1,"lineEnd":40,"totalLines":40,"truncated":false}},"title":"src\common\util\usePersistedState.js","time":{"start":1794264651815,"end":1794264651925}},"metadata":{"copilot":{"itemId":""}},"id":"prt_1c281d823001v7sHnJbHNuLW3e","sessionID":"ses_e3d8ba5beffeEbDEig4oBl9NDv","messageID":"msg_1c281bd1b001V1arbb8kvUDos5"}}
